SELECT @Total=Total FROM dbo.vFacturaSaldo WHERE FacturaID=@Fact;
SET @Monto=ROUND(@Total*0.30,2); SET @F3=DATEADD(hour,7,@Fecha);
EXEC dbo.spRegistrarPago @FacturaID=@Fact,@MetodoPagoID=1,@Monto=@Monto,@UsuarioID=9,@Referencia=N'Abono 1',@Fecha=@F3;
SET @Monto=CONVERT(decimal(12,2),@Total-@Monto);
SET @F4=DATEADD(hour,8,@Fecha);
EXEC dbo.spRegistrarPago @FacturaID=@Fact,@MetodoPagoID=3,@Monto=@Monto,@UsuarioID=9,@Referencia=N'Abono 2',@Fecha=@F4;
