-- Cantidades esperadas: 10 usuarios, 30 clientes, 45 equipos, 60 órdenes, 45 diagnósticos,
-- 40 reparaciones, 30 repuestos, 3 bodegas, 90 inventarios, 8 proveedores, 20 compras,
-- 118 movimientos, 30 facturas y 46 pagos. Todos son datos ficticios.
-- Cuenta demo01=ADMIN; demo02=RECEPCION; demo04=TECNICO; demo07=BODEGA; demo09=CAJA.
-- Contraseña demo: TechCare2026! Hash PBKDF2-HMAC-SHA256, 600000 iteraciones, salt de 16 bytes.
-- Las sales deterministas son exclusivas del fixture; el backend debe generar sales aleatorias en producción.
SELECT COUNT_BIG(1) AS Usuarios FROM dbo.Usuario;
SELECT EstadoCodigo,COUNT_BIG(1) AS Ordenes FROM dbo.OrdenServicio GROUP BY EstadoCodigo;
SELECT EstadoPago,COUNT_BIG(1) AS Facturas FROM dbo.vFacturaSaldo GROUP BY EstadoPago;